def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    value = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        shell = (props.get(element) or {}).get('pymatgen_valence_subshell')
        if fraction is not None and fraction > 0 and shell is not None and len(shell) == 2:
            l = shell[0]
            count = shell[1]
            if l is not None and count is not None:
                total += fraction
                if l == 3:
                    value += fraction * max(0.0, count)
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    nearest = [None] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                x = d / (r[i] + r[j])
                if nearest[i] is None or x < nearest[i]:
                    nearest[i] = x
    total = sum(occ[i] for i in range(n) if nearest[i] is not None)
    return sum(occ[i] * nearest[i] for i in range(n) if nearest[i] is not None) / total if total > 0 else 0.0

