    coordination = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and d <= 1.3 * (r[i] + r[j]):
                coordination[i] += occ[j]
    weights = [occ[i] if r[i] is not None and r[i] > 0 else 0.0 for i in range(n)]
    total = sum(weights)
