def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    signed = [0.0] * n
    weights = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and chi[i] is not None and chi[j] is not None:
                if d <= 1.3 * (r[i] + r[j]):
                    w = occ[j] / max(d * d, 0.01)
                    signed[i] += w * (chi[j] - chi[i])
                    weights[i] += w
    total = sum(occ[i] for i in range(n) if weights[i] > 0)
    return sum(occ[i] * (signed[i] / weights[i]) ** 2 for i in range(n) if weights[i] > 0) / total if total > 0 else 0.0

