def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    adjacency = [[] for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        image = edge.get('image')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and image is not None and len(image) == 3:
            if occ[i] > 0 and occ[j] > 0 and r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                if d <= 1.25 * (r[i] + r[j]):
                    adjacency[i] += [(j, tuple(image))]
    seen = [False] * n
    shifts = [[0, 0, 0] for i in range(n)]
    value = 0.0
    total = sum(occ)
    for root in range(n):
        if seen[root] or occ[root] <= 0:
            continue
        seen[root] = True
        queue = [root]
        cursor = 0
        component_weight = 0.0
        gram = [[0.0] * 3 for k in range(3)]
        while cursor < len(queue):
            i = queue[cursor]
            cursor += 1
            component_weight += occ[i]
            for j, image in adjacency[i]:
                proposed = [shifts[i][k] + image[k] for k in range(3)]
                if not seen[j]:
                    seen[j] = True
                    shifts[j] = proposed
                    queue += [j]
                else:
                    delta = [proposed[k] - shifts[j][k] for k in range(3)]
                    for a in range(3):
                        for b in range(3):
                            gram[a][b] += delta[a] * delta[b]
        rank = float(np.linalg.matrix_rank(np.array(gram)))
        value += component_weight * rank
    return value / total if total > 0 else 0.0
